t.script:
document.addEventListener('DOMContentLoaded', function() {
    const video = document.getElementById('lmsVideoPlayer');
    const wm1 = document.getElementById('floatingWatermark1');
    const wm2 = document.getElementById('floatingWatermark2');
    const wm3 = document.getElementById('floatingWatermark3');
    const progressSpan = document.getElementById('progressPercent');

    const lessonId = ;
    let lastSavedPosition = ;
    let maxAllowedPosition = lastSavedPosition;

    // Resume playback from last saved progress
    if (lastSavedPosition > 0 && video) {
        video.currentTime = lastSavedPosition;
    }

    // Anti-Skip / Anti-Fast-Forward Enforcement (FR-LMS-007)
    if (video) {
        video.addEventListener('timeupdate', function() {
            if (video.currentTime > maxAllowedPosition) {
                maxAllowedPosition = video.currentTime;
            }
            if (video.duration > 0) {
                const pct = Math.min(100, Math.round((maxAllowedPosition / video.duration) * 100));
                if (progressSpan) progressSpan.textContent = pct + '%';
            }
        });

        video.addEventListener('seeking', function() {
            // Block skipping beyond allowed watch buffer
            if (video.currentTime > maxAllowedPosition + 2) {
                video.currentTime = maxAllowedPosition;
            }
        });

        // Periodic Heartbeat to server every 5 seconds (FR-LMS-008)
        setInterval(function() {
            if (!video.paused && video.duration > 0) {
                fetch('/lms/video/heartbeat', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    body: JSON.stringify({
                        jsonrpc: "2.0",
                        method: "call",
                        params: {
                            lesson_id: lessonId,
                            current_time: video.currentTime,
                            duration: video.duration
                        }
                    })
                }).then(r => r.json()).then(data => {
                    if (data.result && data.result.allowed_position) {
                        maxAllowedPosition = Math.max(maxAllowedPosition, data.result.allowed_position);
                    }
                }).catch(err => console.debug("Heartbeat error:", err));
            }
        }, 5000);
    }

    // Screen Capture Deterrent: Subtle drifting watermark position
    setInterval(function() {
        if (wm1 && wm2 && wm3) {
            const deltaX = (Math.random() * 8) - 4;
            const deltaY = (Math.random() * 8) - 4;
            wm1.style.top = Math.max(10, Math.min(80, 15 + deltaY)) + '%';
            wm1.style.left = Math.max(10, Math.min(75, 20 + deltaX)) + '%';
            wm2.style.top = Math.max(20, Math.min(85, 60 - deltaY)) + '%';
            wm2.style.left = Math.max(15, Math.min(80, 45 - deltaX)) + '%';
        }
    }, 8000);

    // Prevent PrintScreen and key recording combinations
    document.addEventListener('keyup', function(e) {
        if (e.key === 'PrintScreen' || (e.ctrlKey && (e.key === 'p' || e.key === 's'))) {
            e.preventDefault();
            alert("Screen capture is disabled on Bunna Bank LMS protected learning assets.");
        }
    });
});
